/**
 * Exportador DOCX — Cartão de Ponto
 *
 * Estratégia: preenche o template oficial (modelo DOCX real) via JSZip,
 * substituindo placeholders e inserindo horários nas células dos dias.
 * Preserva 100% do layout, fontes, bordas e rodapé do documento original.
 */

import JSZip from 'jszip'
import { saveAs } from 'file-saver'
import { isWeekend, eachDayOfInterval, format, getDay } from 'date-fns'
import type { WorkRecord, Profile, Periodo } from '@/types'
import { agruparPorDia } from '@/features/work-records/calculations'

// Template DOCX do modelo oficial codificado em base64
const TEMPLATE_B64 = ''

const MESES_PT: Record<number, string> = {
  1:'JANEIRO',2:'FEVEREIRO',3:'MARÇO',4:'ABRIL',5:'MAIO',6:'JUNHO',
  7:'JULHO',8:'AGOSTO',9:'SETEMBRO',10:'OUTUBRO',11:'NOVEMBRO',12:'DEZEMBRO',
}

/** Converte base64 para ArrayBuffer */
function b64ToArrayBuffer(b64: string): ArrayBuffer {
  const bin = atob(b64)
  const buf = new ArrayBuffer(bin.length)
  const arr = new Uint8Array(buf)
  for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i)
  return buf
}

/** Substitui texto simples no XML */
function replaceText(xml: string, old: string, novo: string): string {
  return xml.replaceAll(`<w:t>${old}</w:t>`, `<w:t>${novo}</w:t>`)
}

/** Run XML com horário formatado */
function makeRun(hora: string): string {
  const h = hora.slice(0, 5) // garantir HH:mm
  return `<w:r><w:rPr><w:rFonts w:cs="Arial"/><w:color w:val="auto"/><w:sz w:val="16"/><w:szCs w:val="16"/></w:rPr><w:t>${h}</w:t></w:r>`
}

/**
 * Preenche os 6 campos de horário de uma linha de dia no XML.
 * horarios: [entrada_manha, saida_manha, entrada_tarde, saida_tarde, entrada_noite, saida_noite]
 */
function preencherLinhaDia(xml: string, diaStr: string, horarios: string[]): string {
  const pattern = `<w:t>${diaStr}</w:t>`
  const idx = xml.indexOf(pattern)
  if (idx < 0) return xml

  const trStart = xml.lastIndexOf('<w:tr ', idx)
  const trEnd = xml.indexOf('</w:tr>', idx) + 7
  if (trStart < 0 || trEnd < 7) return xml

  const trOriginal = xml.slice(trStart, trEnd)

  // Dividir a TR nos seus TCs
  const tcRegex = /<w:tc>[\s\S]*?<\/w:tc>/g
  const tcs: string[] = []
  let m: RegExpExecArray | null
  while ((m = tcRegex.exec(trOriginal)) !== null) tcs.push(m[0])

  if (tcs.length < 2) return xml

  let trNew = trOriginal
  for (let i = 0; i < 6; i++) {
    const hora = horarios[i] ?? ''
    if (!hora) continue
    const tcIdx = i + 1
    if (tcIdx >= tcs.length) break

    const tcOld = tcs[tcIdx]
    // Inserir o run antes do </w:p> no TC
    const tcSemRuns = tcOld.replace(/<w:r>[\s\S]*?<\/w:r>/g, '')
const tcNew = tcSemRuns.replace('</w:p>', makeRun(hora) + '</w:p>')
    trNew = trNew.replace(tcOld, tcNew)
  }

  return xml.slice(0, trStart) + trNew + xml.slice(trEnd)
}

// ─── Exportação principal ─────────────────────────────────────────────────────

export async function gerarCartaoPonto(
  records: WorkRecord[],
  profile: Profile,
  periodo: Periodo
): Promise<void> {
  const agrupado = agruparPorDia(records)
  const dias = eachDayOfInterval({ start: periodo.inicio, end: periodo.fim })

  // Carregar e descompactar o template
  const buf = b64ToArrayBuffer(TEMPLATE_B64)
  const zip = await JSZip.loadAsync(buf)
  let xml = await zip.file('word/document.xml')!.async('string')

  // ── Substituições de cabeçalho ──────────────────────────────────────────────
  xml = replaceText(xml, 'Andresson Mouzinho de Sousa', profile.nome)
  xml = replaceText(xml, 'CETEC PALMAS', profile.lotacao)
  xml = replaceText(xml, '1806', profile.matricula)
  xml = replaceText(xml, ' Técnico em Informática 1', ` ${profile.funcao}`)
  xml = replaceText(xml, 'Neuzely Aguiar dos Santos', profile.responsavel)
  xml = replaceText(xml, 'MAIO', MESES_PT[periodo.fim.getMonth() + 1] ?? 'JUNHO')
  xml = replaceText(xml, '2026', format(periodo.fim, 'yyyy'))

  // Substituir C. Custo (campo FORMTEXT vazio — inserir antes do fldChar end)
  if (profile.centro_custo) {
    xml = xml.replace(
      '<w:fldChar w:fldCharType="separate"/><w:t>     </w:t><w:fldChar w:fldCharType="end"/>',
      `<w:fldChar w:fldCharType="separate"/><w:t>${profile.centro_custo}</w:t><w:fldChar w:fldCharType="end"/>`
    )
  }

  // ── Preenchimento das linhas de dias ────────────────────────────────────────
  for (const dia of dias) {
    const isoData = format(dia, 'yyyy-MM-dd')
    const diaNum = format(dia, 'dd') // "20", "01", etc.
    const ehFds = isWeekend(dia)
    if (ehFds) continue // fim de semana já tem "---" no template

    const recordsDia = agrupado.get(isoData) ?? []
    if (recordsDia.length === 0) continue

    const sorted = [...recordsDia].sort((a, b) => a.hora.localeCompare(b.hora))
    const horarios = [
      sorted[0]?.hora ?? '',
      sorted[1]?.hora ?? '',
      sorted[2]?.hora ?? '',
      sorted[3]?.hora ?? '',
      sorted[4]?.hora ?? '',
      sorted[5]?.hora ?? '',
    ]

    xml = preencherLinhaDia(xml, diaNum, horarios)
  }

  // ── Remontar e salvar ───────────────────────────────────────────────────────
  zip.file('word/document.xml', xml)
  const blob = await zip.generateAsync({ type: 'blob', mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' })
  const nomeArquivo = `Cartao_Ponto_${profile.nome.replace(/\s+/g, '_')}_${format(periodo.fim, 'MMMyyyy').toUpperCase()}.docx`
  saveAs(blob, nomeArquivo)
}
